using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_as_json()
    {
        HttpRequestMessage? capturedRequest = null;
        string? capturedBody = null;

        var handler = new StubHttpMessageHandler(async request =>
        {
            capturedRequest = request;
            capturedBody = request.Content is null ? null : await request.Content.ReadAsStringAsync();
            return JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""");
        });

        var gateway = CreateGateway(handler);

        await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);

        Assert.NotNull(capturedRequest);
        Assert.Equal(HttpMethod.Post, capturedRequest!.Method);
        Assert.Equal("/v1/authorizations", capturedRequest.RequestUri!.PathAndQuery);

        using var payload = JsonDocument.Parse(capturedBody!);
        Assert.Equal("ORD-7", payload.RootElement.GetProperty("reference").GetString());
        Assert.Equal(12.50m, payload.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", payload.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_Approved()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"approved"}""")));

        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_Declined()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"declined"}""")));

        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognised_status_value_is_treated_as_Declined()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, """{"status":"pending_review"}""")));

        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_read_back_as_Declined_without_reading_the_body()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.PaymentRequired, "not json at all")));

        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_server_error_response_throws_instead_of_being_treated_as_a_decision()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.InternalServerError, """{"status":"approved"}""")));

        var gateway = CreateGateway(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task An_empty_200_body_is_read_back_as_Declined()
    {
        var handler = new StubHttpMessageHandler(_ =>
            Task.FromResult(JsonResponse(HttpStatusCode.OK, "null")));

        var gateway = CreateGateway(handler);

        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "EUR"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    private static Infrastructure.HttpPaymentGateway CreateGateway(HttpMessageHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example.test") };
        return new Infrastructure.HttpPaymentGateway(client);
    }

    private static HttpResponseMessage JsonResponse(HttpStatusCode statusCode, string body) => new(statusCode)
    {
        Content = new StringContent(body, System.Text.Encoding.UTF8, "application/json"),
    };

    private sealed class StubHttpMessageHandler(Func<HttpRequestMessage, Task<HttpResponseMessage>> respond) : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken cancellationToken)
            => respond(request);
    }
}

